const items = $input.all();
const required = ['Patient Number','Heart Rate (bpm)','SpO2 Level (%)','Systolic Blood Pressure (mmHg)','Diastolic Blood Pressure (mmHg)','Body Temperature (°C)','Fall Detection','Predicted Disease','Data Accuracy (%)','Heart Rate Alert','SpO2 Level Alert','Blood Pressure Alert','Temperature Alert'];
return items.map(item => {
  const row = item.json;
  const missingFields = required.filter(k => row[k] === undefined || row[k] === null || String(row[k]).trim() === '');
  const accuracy = Number(row['Data Accuracy (%)']);
  const accuracyReview = Number.isFinite(accuracy) && accuracy < 80;
  return { json: { ...row, _dataQuality: { missingFields, accuracyReview, accuracyReviewNote: accuracyReview ? 'Below configurable 80% engineering review threshold; not a clinical standard.' : null } } };
});

const items = $input.all();
const alertFields = ['Heart Rate Alert','SpO2 Level Alert','Blood Pressure Alert','Temperature Alert'];
return items.map(item => {
  const row = item.json;
  const abnormalAlerts = alertFields.filter(k => String(row[k] ?? '').trim().toUpperCase() === 'ABNORMAL');
  const fall = ['yes','true','1','detected','fall'].includes(String(row['Fall Detection'] ?? '').trim().toLowerCase());
  return { json: { ...row, _monitoring: { abnormalAlerts, positiveFallFlag: fall, requiresReview: abnormalAlerts.length > 0 || fall || Boolean(row._dataQuality?.accuracyReview) } } };
});

const items = $input.all();
const alertFields = ['Heart Rate Alert','SpO2 Level Alert','Blood Pressure Alert','Temperature Alert'];
const alertCounts = {};
for (const field of alertFields) {
  let abnormal = 0, normal = 0, otherOrMissing = 0;
  for (const item of items) { const v = String(item.json[field] ?? '').trim().toUpperCase(); if (v === 'ABNORMAL') abnormal++; else if (v === 'NORMAL') normal++; else otherOrMissing++; }
  alertCounts[field] = { abnormal, normal, otherOrMissing };
}
const positiveFall = items.filter(i => ['yes','true','1','detected','fall'].includes(String(i.json['Fall Detection'] ?? '').trim().toLowerCase()));
const reviewRecords = items.filter(i => i.json._monitoring?.requiresReview);
const qualityIssues = items.filter(i => (i.json._dataQuality?.missingFields?.length || 0) > 0 || i.json._dataQuality?.accuracyReview);
const diseaseCounts = {};
for (const i of items) { const disease = String(i.json['Predicted Disease'] ?? 'Unknown'); diseaseCounts[disease] = (diseaseCounts[disease] || 0) + 1; }
const topDiseases = Object.entries(diseaseCounts).sort((a,b) => b[1]-a[1]).slice(0,20).map(([label,count]) => ({label,count}));
const samples = reviewRecords.slice(0,25).map(i => ({ patientNumber: i.json['Patient Number'], predictedDisease: i.json['Predicted Disease'], abnormalAlerts: i.json._monitoring.abnormalAlerts, positiveFallFlag: i.json._monitoring.positiveFallFlag, dataAccuracy: i.json['Data Accuracy (%)'], quality: i.json._dataQuality }));
return [{ json: { workflow: 'Agentic Health Monitoring - Static CSV Multi-Agent (No Webhook)', analysisType: 'cross-sectional synthetic dataset', totalRecords: items.length, uniquePatientNumbers: new Set(items.map(i => String(i.json['Patient Number'] ?? '')).filter(Boolean)).size, alertCounts, positiveFallRecords: positiveFall.length, recordsWithReviewFlags: reviewRecords.length, recordsWithDataQualityFlags: qualityIssues.length, topPredictedDiseaseLabels: topDiseases, sampleReviewRecords: samples, limitations: ['Dataset has no timestamp/date column; no longitudinal trend is calculated.','Supplied predicted disease and alert fields are not independently validated clinical outcomes.','Research prototype only; not a diagnostic or emergency service.'] } }];
